pub fn contar(palavras: Vec<String>) -> HashMap<String, i32> {
    let mut contagem = HashMap::new();
    for palavra in palavras {
        *contagem.entry(palavra).or_insert(0) += 1;
    }
    contagem
}

use std::collections::HashMap;

pub fn apuramento(votos: Vec<String>) -> String {
    let mut contagem = HashMap::new();
    for voto in votos {
        *contagem.entry(voto).or_insert(0) += 1;
    }
    let da_ana = match contagem.get("ana") {
        Some(n) => *n,
        None => 0,
    };
    format!("ana: {} votos", da_ana)
}

pub mod urna {
    pub struct Urna {
        pub votos: Vec<String>,
    }

    impl Urna {
        pub fn nova() -> Urna {
            Urna { votos: vec![] }
        }

        pub fn recebe(&mut self, voto: String) {
            self.votos.push(voto);
        }

        pub fn votos(&self) -> Vec<String> {
            self.votos.clone()
        }
    }

    pub fn empurra(urna: &mut Urna, voto: String) {
        super::urna::Urna::recebe(urna, voto);
    }

    pub fn lista(urna: &Urna) -> Vec<String> {
        super::urna::Urna::votos(urna)
    }
}

use std::collections::HashMap;
use urna::Urna;

pub fn apura(caixa: Urna) -> HashMap<String, i32> {
    let mut contagem = HashMap::new();
    for voto in urna::lista(&caixa) {
        *contagem.entry(voto).or_insert(0) += 1;
    }
    contagem
}
